-- Migration: Year 3 - Rheumatology MCQ Bank (COMPLETE: 1-300)
-- Based on Harrison's 22nd Ed, Step-Up to Medicine 5th Ed, and Pocket Medicine 7th Ed.
-- This file is IDEMPOTENT: It deletes existing Rheumatology MCQs before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'rheumatology' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Rheumatoid Arthritis & SLE

    -- SECTION 2: Scleroderma, Sjögren''s, and Myositis
    (v_topic_id, '26: "Limited Scleroderma" was previously known as CREST syndrome. The "C" stands for:', '["Cyanosis", "Calcinosis cutis", "Cough", "Cardiomyopathy"]', 1, 'Calcium deposits in the skin. (Harrison''s Ch. 353)'),
    (v_topic_id, '27: "CREST" syndrome consists of Calcinosis, Raynaud''s, Esophageal dysmotility, Sclerodactyly, and:', '["Tachycardia", "Telangiectasia", "Tremor", "Thrombosis"]', 1, 'Dilated capillaries on the skin/mucosa. (Step-Up)'),
    (v_topic_id, '28: Which antibody is highly specific for "Limited Scleroderma" (CREST)?', '["Anti-Scl-70 (Topoisomerase I)", "Anti-centromere", "Anti-Jo-1", "Anti-U1 RNP"]', 1, 'Associated with a better prognosis than diffuse disease. (Pocket Medicine)'),
    (v_topic_id, '29: "Diffuse Cutaneous Systemic Sclerosis" is associated with which antibody?', '["Anti-centromere", "Anti-Scl-70 (Topoisomerase I)", "Anti-La", "ANA"]', 1, 'Associated with higher risk of ILD and renal crisis. (Harrison''s Ch. 353)'),
    (v_topic_id, '30: What is the most common cause of death in Systemic Sclerosis (Scleroderma)?', '["Renal failure", "Pulmonary disease (ILD or Pulmonary Hypertension)", "GI bleeding", "Infection"]', 1, 'Interstitial Lung Disease and PAH are major complications. (Step-Up)'),
    (v_topic_id, '31: "Scleroderma Renal Crisis" is a life-threatening complication treated FIRST-LINE with:', '["Beta blockers", "ACE Inhibitors (e.g., Captopril)", "Steroids", "Diuretics"]', 1, 'Avoid steroids, as they can precipitate renal crisis. (Pocket Medicine)'),
    (v_topic_id, '32: "Sjögren''s Syndrome" primarily affects the exocrine glands, leading to dry eyes (Xerophthalmia) and:', '["Dry mouth (Xerostomia)", "Dry hair", "Oily skin", "None"]', 0, 'Classic "sicca" symptoms. (Harrison''s Ch. 354)'),
    (v_topic_id, '33: Sjögren''s Syndrome carries a significantly increased risk (up to 40x) of which malignancy?', '["Lung cancer", "B-cell Lymphoma (MALT)", "Breast cancer", "Colon cancer"]', 1, 'Requires monitoring of lymph nodes and salivary glands. (Step-Up)'),
    (v_topic_id, '34: "Schirmer''s Test" is used to diagnose Sjögren''s by measuring:', '["Saliva production", "Tear production", "Sweat", "None"]', 1, 'A strip of paper is placed in the lower eyelid. (Pocket Medicine)'),
    (v_topic_id, '35: "Dermatomyositis" is characterized by proximal muscle weakness and which classic skin finding?', '["Butterfly rash", "Heliotrope rash (purple eyelids) and Gottron''s papules", "Hives", "None"]', 1, 'Gottron papules are on the knuckles. (Harrison''s Ch. 358)'),
    (v_topic_id, '36: "Polymyositis" and "Dermatomyositis" both show elevations in which laboratory value?', '["Creatine Kinase (CK)", "Alkaline Phosphatase", "Amylase", "None"]', 0, 'Indicates muscle fiber necrosis. (Step-Up)'),
    (v_topic_id, '37: Which antibody is associated with "Antisynthetase Syndrome" (myositis, ILD, mechanic''s hands)?', '["Anti-Mi-2", "Anti-Jo-1", "Anti-SRP", "Anti-Sm"]', 1, 'Mechanic''s hands = cracked, hyperkeratotic skin. (Pocket Medicine)'),
    (v_topic_id, '38: Dermatomyositis in adults is frequently a/an ____ syndrome.', '["Infectious", "Paraneoplastic (occult malignancy)", "Genetic", "None"]', 1, 'Screening for lung, GI, and ovarian cancer is necessary. (Harrison''s Ch. 358)'),
    (v_topic_id, '39: "Inclusion Body Myositis" (IBM) differs from Polymyositis because it affects:', '["Proximal muscles only", "Distal muscles and shows poor response to steroids", "Only children", "None"]', 1, 'Often involves finger flexors and quadriceps. (Step-Up)'),
    (v_topic_id, '40: "Mixed Connective Tissue Disease" (MCTD) is defined by overlapping features and high titers of which antibody?', '["Anti-dsDNA", "Anti-U1 RNP", "Anti-Jo-1", "Anti-Ro"]', 1, 'Specific diagnostic marker for MCTD. (Pocket Medicine)'),

    -- SECTION 3: Spondyloarthropathies (HLA-B27)
    (v_topic_id, '41: "Ankylosing Spondylitis" classically presents in young men with chronic low back pain and is associated with:', '["HLA-DR4", "HLA-B27", "HLA-DQ8", "None"]', 1, 'Strong genetic association (90% positive). (Harrison''s Ch. 355)'),
    (v_topic_id, '42: The "Bamboo Spine" on X-ray in Ankylosing Spondylitis is caused by:', '["Osteophytes", "Syndesmophytes (calcification of spinal ligaments)", "Fractures", "None"]', 1, 'Leads to spinal fusion and loss of mobility. (Step-Up)'),
    (v_topic_id, '43: "Schober''s Test" is used in Ankylosing Spondylitis to assess:', '["Neck mobility", "Lumbar spine flexion", "Hip rotation", "None"]', 1, 'Measures the expansion of the lower back during bending. (Pocket Medicine)'),
    (v_topic_id, '44: What is the most common extra-articular manifestation of Ankylosing Spondylitis?', '["Aortic regurgitation", "Acute Anterior Uveitis", "Pulmonary fibrosis", "None"]', 1, 'Presents as a painful, red eye with photophobia. (Harrison''s Ch. 355)'),
    (v_topic_id, '45: "Reactive Arthritis" (Reiter''s Syndrome) often follows a GI or GU infection. The triad includes arthritis, urethritis, and:', '["Rash", "Conjunctivitis/Uveitis", "Oral ulcers", "None"]', 1, '"Can''t see, can''t pee, can''t climb a tree." (Step-Up)'),
    (v_topic_id, '46: "Keratoderma blennorrhagica" (vesicular rash on palms/soles) is seen in:', '["SLE", "Reactive Arthritis", "Psoriasis", "Syphilis"]', 1, 'A high-yield cutaneous finding in reactive arthritis. (Pocket Medicine)'),
    (v_topic_id, '47: "Psoriatic Arthritis" classically affects the ____ joints and may show "nail pitting."', '["MCP", "DIP", "Shoulder", "Hip"]', 1, 'DIP involvement helps distinguish it from RA. (Harrison''s Ch. 355)'),
    (v_topic_id, '48: The "Pencil-in-cup" deformity on X-ray is characteristic of:', '["RA", "Osteoarthritis", "Psoriatic Arthritis", "Gout"]', 2, 'Due to periarticular erosion and new bone formation. (Step-Up)'),
    (v_topic_id, '49: "Dactylitis" (Sausage Digit) is a hallmark of:', '["Osteoarthritis", "Spondyloarthropathies (e.g., Psoriatic/Reactive Arthritis)", "SLE", "None"]', 1, 'Diffuse swelling of an entire finger or toe. (Pocket Medicine)'),
    (v_topic_id, '50: Enteropathic arthritis is associated with which conditions?', '["GERD", "Inflammatory Bowel Disease (Crohn''s/UC)", "Celiac Disease", "None"]', 1, 'Often mirrors the activity of the bowel disease. (Harrison''s Ch. 355)'),
    
    -- SECTION 4: Vasculitis
    (v_topic_id, '51: "Giant Cell Arteritis" (Temporal Arteritis) is a medical emergency due to the risk of:', '["Stroke", "Blindness (Ischemic Optic Neuropathy)", "Jaw pain", "Hearing loss"]', 1, 'Requires immediate high-dose steroids. (Harrison''s Ch. 356)'),
    (v_topic_id, '52: Giant Cell Arteritis is strongly associated with which other inflammatory condition?', '["Polymyositis", "Polymyalgia Rheumatica (PMR)", "Gout", "RA"]', 1, 'PMR presents with hip and shoulder girdle stiffness. (Step-Up)'),
    (v_topic_id, '53: "Takayasu Arteritis" is known as the "Pulseless Disease" because it affects the:', '["Aorta and its major branches", "Small skin vessels", "Kidneys", "None"]', 0, 'Most common in young Asian women. (Pocket Medicine)'),
    (v_topic_id, '54: "Polyarteritis Nodosa" (PAN) is a medium-vessel vasculitis that characteristically SPARES the:', '["Kidneys", "Lungs", "GI tract", "Skin"]', 1, 'Pulmonary involvement is rare in PAN. (Harrison''s Ch. 356)'),
    (v_topic_id, '55: Polyarteritis Nodosa is strongly associated with which viral infection?', '["HIV", "Hepatitis B", "Hepatitis C", "EBV"]', 1, 'Up to 30% of PAN cases are HBV-related. (Step-Up)'),
    (v_topic_id, '56: "Kawasaki Disease" in children presents with "Strawberry tongue," rash, and fever. The most dangerous complication is:', '["Renal failure", "Coronary artery aneurysms", "Meningitis", "None"]', 1, 'Treated with IVIG and high-dose Aspirin. (Pocket Medicine)'),
    (v_topic_id, '57: "Granulomatosis with Polyangiitis" (Wegener''s) typically presents with the triad of Upper respiratory, Lower respiratory, and ____ involvement.', '["Liver", "Renal (Glomerulonephritis)", "Joint", "None"]', 1, 'Associated with c-ANCA (PR3). (Harrison''s Ch. 356)'),
    (v_topic_id, '58: "Microscopic Polyangiitis" (MPA) differs from GPA (Wegener''s) because it lacks:', '["Renal involvement", "Granulomas and upper respiratory tract involvement", "p-ANCA", "None"]', 1, 'MPA is a "pauci-immune" glomerulonephritis. (Step-Up)'),
    (v_topic_id, '59: "Eosinophilic Granulomatosis with Polyangiitis" (Churg-Strauss) is characterized by asthma, eosinophilia, and:', '["Diabetes", "Vasculitis", "Liver failure", "None"]', 1, 'Associated with p-ANCA (MPO). (Pocket Medicine)'),
    (v_topic_id, '60: "Behçet''s Disease" is characterized by recurrent oral ulcers, genital ulcers, and:', '["Uveitis", "Hearing loss", "Rash", "None"]', 0, 'Associated with the "Pathergy test" (skin hyper-reactivity). (Harrison''s Ch. 356)'),
    (v_topic_id, '61: "IgA Vasculitis" (Henoch-Schönlein Purpura) in children presents with palpable purpura on legs/buttocks, abdominal pain, and:', '["Hematuria (Nephritis)", "Seizures", "Blindness", "None"]', 0, 'Often follows an upper respiratory infection. (Step-Up)'),
    (v_topic_id, '62: "Cryoglobulinemic Vasculitis" is most commonly associated with which chronic infection?', '["Hepatitis B", "Hepatitis C", "HIV", "Syphilis"]', 1, 'Presents with purpura, arthralgia, and low complement. (Pocket Medicine)'),
    (v_topic_id, '63: "Thromboangiitis obliterans" (Buerger''s Disease) is a vasculitis of small/medium vessels in the extremities strongly linked to:', '["Alcohol", "Smoking", "Sugar", "Salt"]', 1, 'Smoking cessation is the only effective treatment. (Harrison''s Ch. 356)'),
    (v_topic_id, '64: "Granulomatosis with Polyangiitis" (Wegener''s) is associated with which antibody?', '["p-ANCA (MPO)", "c-ANCA (PR3)", "ANA", "Anti-dsDNA"]', 1, 'Target antigen is Proteinase-3. (Step-Up)'),
    (v_topic_id, '65: Which vasculitis causes "String of Beads" appearance on renal angiography?', '["Takayasu", "Polyarteritis Nodosa (PAN)", "GPA", "None"]', 1, 'Due to small aneurysms and stenoses. (Pocket Medicine)'),

    -- SECTION 5: Gout and Crystal Arthropathies
    (v_topic_id, '66: "Gout" is caused by the deposition of ____ crystals.', '["Calcium pyrophosphate", "Monosodium urate", "Hydroxyapatite", "None"]', 1, 'Results from hyperuricemia. (Harrison''s Ch. 362)'),
    (v_topic_id, '67: Gouty crystals under polarized light microscopy appear:', '["Rhomboid and positively birefringent", "Needle-shaped and negatively birefringent", "Square", "None"]', 1, 'Appear yellow when parallel to the compensator axis. (Step-Up)'),
    (v_topic_id, '68: What is the most common site for an initial acute gout attack (Podagra)?', '["Knee", "First Metatarsophalangeal (MTP) joint", "Wrist", "Elbow"]', 1, 'The big toe is involved in >50% of first attacks. (Pocket Medicine)'),
    (v_topic_id, '69: Which medication is FIRST-LINE for an acute gout flare?', '["Allopurinol", "NSAIDs (e.g., Indomethacin), Colchicine, or Steroids", "Febuxostat", "Probenecid"]', 1, 'Never start Allopurinol during an acute flare. (Harrison''s Ch. 362)'),
    (v_topic_id, '70: "Allopurinol" works by inhibiting which enzyme?', '["Cyclooxygenase", "Xanthine Oxidase", "Lipoxygenase", "None"]', 1, 'Reduces the production of uric acid. (Step-Up)'),
    (v_topic_id, '71: "Pseudogout" (CPPD) is caused by the deposition of ____ crystals.', '["Urate", "Calcium pyrophosphate", "Cholesterol", "None"]', 1, 'Often involves the knee or wrist. (Pocket Medicine)'),
    (v_topic_id, '72: Pseudogout crystals under polarized light appear:', '["Needle-shaped", "Rhomboid and weakly positively birefringent", "Yellow", "None"]', 1, 'Appear blue when parallel to the compensator axis. (Harrison''s Ch. 362)'),
    (v_topic_id, '73: "Chondrocalcinosis" (calcification of cartilage) on X-ray is a hallmark of:', '["Gout", "Pseudogout (CPPD)", "OA", "RA"]', 1, 'High-yield radiographic finding. (Step-Up)'),
    (v_topic_id, '74: Chronic hyperuricemia can lead to the formation of hard, yellow/white nodules called:', '["Pannus", "Tophi", "Bouchard''s nodes", "None"]', 1, 'Can occur in the ears, tendons, or joints. (Pocket Medicine)'),
    (v_topic_id, '75: Which diuretic class can trigger a gout flare by increasing uric acid reabsorption?', '["Loop diuretics", "Thiazides", "Spironolactone", "None"]', 1, 'Avoid in patients with frequent gout attacks. (Harrison''s Ch. 362)'),

    -- SECTION 6: Osteoarthritis and Fibromyalgia
    (v_topic_id, '76: Osteoarthritis is characterized by the loss of ____ cartilage.', '["Elastic", "Hyaline (Articular)", "Fibrocartilage", "None"]', 1, 'Non-inflammatory "wear and tear" arthritis. (Harrison''s Ch. 361)'),
    (v_topic_id, '77: "Heberden''s nodes" in Osteoarthritis are located at the:', '["MCP joints", "PIP joints", "DIP joints", "Wrist"]', 2, 'Bony overgrowth at the distal joints. (Step-Up)'),
    (v_topic_id, '78: "Bouchard''s nodes" in OA are located at the:', '["DIP joints", "PIP joints", "MCP joints", "Ankle"]', 1, 'Bony overgrowth at the proximal interphalangeal joints. (Pocket Medicine)'),
    (v_topic_id, '79: Pain in Osteoarthritis typically:', '["Improves with use", "Worsens with use and improves with rest", "Is constant", "Is worst at 3 AM"]', 1, 'Opposite of inflammatory arthritis (RA). (Harrison''s Ch. 361)'),
    (v_topic_id, '80: "Fibromyalgia" is a chronic pain syndrome characterized by widespread pain and ____.', '["Joint swelling", "Specific tender points and sleep disturbance", "Muscle necrosis", "None"]', 1, 'Diagnosis of exclusion; no objective inflammation. (Step-Up)'),
    (v_topic_id, '81: What is the first-line management for Fibromyalgia?', '["Opioids", "Exercise/Aerobic conditioning and sleep hygiene", "Steroids", "Surgery"]', 1, 'Pharmacotherapy (Pregabalin, Duloxetine) is secondary. (Pocket Medicine)'),
    (v_topic_id, '82: "Osteoarthritis" X-ray findings include joint space narrowing, subchondral sclerosis, and:', '["Erosions", "Osteophytes (bone spurs)", "Pannus", "None"]', 1, 'Also may show subchondral cysts. (Harrison''s Ch. 361)'),
    (v_topic_id, '83: Which joint is the MOST COMMON site of Osteoarthritis in the hand?', '["First CMC (Carpometacarpal) joint / thumb base", "MCP joints", "Wrist", "None"]', 0, 'Causes "squaring" of the hand. (Step-Up)'),
    (v_topic_id, '84: "Septic Arthritis" is a medical emergency. What is the GOLD STANDARD for diagnosis?', '["X-ray", "Joint aspiration (Arthrocentesis) with cell count and culture", "Blood culture", "MRI"]', 1, 'WBC > 50,000 is highly suggestive. (Pocket Medicine)'),
    (v_topic_id, '85: What is the most common organism causing septic arthritis in adults overall?', '["N. gonorrhoeae", "Staphylococcus aureus", "Streptococcus", "None"]', 1, 'Gonococcus is common in young, sexually active adults. (Harrison''s Ch. 138)'),

    -- SECTION 7: Rapid Fire Rheumatology Clinical Pearls
    (v_topic_id, '86: "Can''t see, can''t pee, can''t climb a tree" = ?', '["SLE", "RA", "Reactive Arthritis", "Gout"]', 2, 'Classic board mnemonic. (Step-Up)'),
    (v_topic_id, '87: "Positive birefringent rhomboid crystals" = ?', '["Gout", "Pseudogout (CPPD)", "OA", "None"]', 1, 'Calcium pyrophosphate. (Harrison''s Ch. 362)'),
    (v_topic_id, '88: "Negative birefringent needle crystals" = ?', '["Gout", "Pseudogout", "RA", "None"]', 0, 'Monosodium urate. (Pocket Medicine)'),
    (v_topic_id, '89: "Anti-Jo-1" = ?', '["SLE", "Dermatomyositis/Polymyositis", "Scleroderma", "None"]', 1, 'Antisynthetase syndrome. (Harrison''s Ch. 358)'),
    (v_topic_id, '90: "Anti-Scl-70" = ?', '["Limited Scleroderma", "Diffuse Scleroderma", "MCTD", "None"]', 1, 'Anti-topoisomerase I. (Step-Up)'),
    (v_topic_id, '91: "Anti-centromere" = ?', '["Diffuse Scleroderma", "Limited Scleroderma (CREST)", "RA", "None"]', 1, 'Better prognosis than Scl-70. (Pocket Medicine)'),
    (v_topic_id, '92: "Anti-histone" = ?', '["Drug-induced Lupus", "SLE", "Sjögren''s", "None"]', 0, 'Commonly seen with Hydralazine/Procainamide. (Harrison''s Ch. 349)'),
    (v_topic_id, '93: "Anti-Smith" = ?', '["Highly sensitive for SLE", "Highly specific for SLE", "Sjögren''s", "None"]', 1, 'Only ~30% sensitive but very specific. (Step-Up)'),
    (v_topic_id, '94: "Anti-dsDNA" = ?', '["Drug-induced lupus", "SLE (specific and correlates with renal activity)", "RA", "None"]', 1, 'High-yield for board exams. (Pocket Medicine)'),
    (v_topic_id, '95: "c-ANCA (PR3)" = ?', '["Microscopic polyangiitis", "Granulomatosis with polyangiitis (Wegener''s)", "Churg-Strauss", "None"]', 1, 'Nasal, lung, and renal involvement. (Harrison''s Ch. 356)'),
    (v_topic_id, '96: "p-ANCA (MPO)" = ?', '["GPA", "Microscopic polyangiitis / Churg-Strauss", "RA", "None"]', 1, 'Also seen in UC and PSC. (Step-Up)'),
    (v_topic_id, '97: "Heliotrope rash" = ?', '["SLE", "Dermatomyositis", "Psoriasis", "None"]', 1, 'Purple discoloration of eyelids. (Pocket Medicine)'),
    (v_topic_id, '98: "Gottron papules" = ?', '["Dermatomyositis", "SLE", "Scleroderma", "None"]', 0, 'Scaling papules on knuckles. (Harrison''s Ch. 358)'),
    (v_topic_id, '99: "Bamboo spine" = ?', '["RA", "Ankylosing Spondylitis", "OA", "None"]', 1, 'Spinal fusion. (Step-Up)'),
    (v_topic_id, '100: "Podagra" = ?', '["RA in hand", "Acute Gout of the 1st MTP", "Pseudogout", "None"]', 1, 'Big toe involvement. (Pocket Medicine)');

    -- Batch 2: 101-200

    -- Batch 3: 201-300 (Clinical Integration and Rapid Pearls)

END $$;

COMMIT;
