    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which joint group is TYPICALLY SPARED in Rheumatoid Arthritis?', '["Metacarpophalangeal (MCP)", "Proximal Interphalangeal (PIP)", "Distal Interphalangeal (DIP)", "Wrist"]', 2, 'DIP involvement is characteristic of Osteoarthritis or Psoriatic Arthritis, not RA. (Harrison''s Ch. 351)'),
    (v_topic_id, '2: "Morning stiffness" in Rheumatoid Arthritis classically lasts for more than:', '["15 minutes", "30 minutes", "1 hour", "4 hours"]', 2, 'Stiffness >1 hour is a key diagnostic clue for inflammatory arthritis like RA. (Step-Up)'),
    (v_topic_id, '3: Which antibody is MORE SPECIFIC for the diagnosis of Rheumatoid Arthritis than Rheumatoid Factor (RF)?', '["Anti-dsDNA", "Anti-CCP (Cyclic Citrullinated Peptide)", "Anti-Smith", "ANA"]', 1, 'Anti-CCP has a specificity of >95% for RA. (Pocket Medicine)'),
    (v_topic_id, '4: In RA, the "Boutonniere deformity" consists of:', '["PIP extension and DIP flexion", "PIP flexion and DIP hyperextension", "Ulnar deviation", "Radial deviation"]', 1, 'Caused by rupture of the central slip of the extensor tendon. (Harrison''s Ch. 351)'),
    (v_topic_id, '5: "Swan-neck deformity" in RA involves:', '["PIP hyperextension and DIP flexion", "PIP flexion and DIP extension", "MCP subluxation", "None"]', 0, 'Opposite of Boutonniere; involves the volar plate. (Step-Up)'),
    (v_topic_id, '6: "Felty''s Syndrome" is a triad of Rheumatoid Arthritis, Splenomegaly, and:', '["Anemia", "Thrombocytopenia", "Neutropenia", "Leukocytosis"]', 2, 'Increases the risk of serious infections. (Pocket Medicine)'),
    (v_topic_id, '7: What is the FIRST-LINE Disease-Modifying Antirheumatic Drug (DMARD) for most patients with RA?', '["Sulfasalazine", "Hydroxychloroquine", "Methotrexate", "Leflunomide"]', 2, 'Methotrexate is the anchor drug for RA management. (Harrison''s Ch. 351)'),
    (v_topic_id, '8: Patients starting Methotrexate must be supplemented with which vitamin to reduce side effects?', '["Vitamin B12", "Folic Acid", "Vitamin D", "Vitamin C"]', 1, 'Reduces GI toxicity and stomatitis. (Step-Up)'),
    (v_topic_id, '9: Which baseline screening is REQUIRED before starting Hydroxychloroquine?', '["Liver function tests", "Ophthalmologic exam (visual fields/OCT)", "Renal function", "PPD/Quantiferon"]', 1, 'To monitor for rare but serious retinal toxicity. (Pocket Medicine)'),
    (v_topic_id, '10: "Caplan Syndrome" is the association of Rheumatoid Arthritis with:', '["Pneumoconiosis (coal worker''s nodes)", "Pericarditis", "Scleritis", "Vasculitis"]', 0, 'Presents as multiple pulmonary nodules. (Harrison''s Ch. 351)'),
    (v_topic_id, '11: Which screening test is MANDATORY before initiating any TNF-alpha inhibitor (e.g., Etanercept, Infliximab)?', '["HIV test", "Latent TB screening (PPD or IGRA)", "Hepatitis C", "Chest CT"]', 1, 'TNF inhibitors can cause reactivation of latent Tuberculosis. (Step-Up)'),
    (v_topic_id, '12: Systemic Lupus Erythematosus (SLE) is most common in which demographic?', '["Elderly men", "Women of childbearing age (especially African American/Hispanic)", "Children", "Young Caucasian males"]', 1, '90% of SLE patients are women. (Harrison''s Ch. 349)'),
    (v_topic_id, '13: What is the most SENSITIVE screening test for SLE?', '["Anti-dsDNA", "Anti-Smith", "ANA (Antinuclear Antibody)", "Anti-Ro"]', 2, 'Positive in >99% of patients, though not specific. (Pocket Medicine)'),
    (v_topic_id, '14: Which antibody is the MOST SPECIFIC for SLE?', '["ANA", "Anti-Smith", "Anti-histone", "Anti-centromere"]', 1, 'Found in ~30% of SLE patients but highly specific. (Harrison''s Ch. 349)'),
    (v_topic_id, '15: High titers of "Anti-dsDNA" antibodies in SLE are often associated with:', '["Skin rash only", "Lupus Nephritis", "Joint pain", "Hematologic issues"]', 1, 'dsDNA levels often correlate with disease activity, especially renal. (Step-Up)'),
    (v_topic_id, '16: "Drug-Induced Lupus" is most strongly associated with which antibody?', '["Anti-dsDNA", "Anti-Smith", "Anti-histone", "Anti-Ro"]', 2, 'Classically caused by Procainamide, Hydralazine, or Isoniazid. (Pocket Medicine)'),
    (v_topic_id, '17: "Anti-Ro (SS-A)" and "Anti-La (SS-B)" antibodies in a pregnant SLE patient increase the risk of ____ in the neonate.', '["Cleft palate", "Congenital Heart Block", "Seizures", "Kidney failure"]', 1, 'Causes neonatal lupus syndrome. (Harrison''s Ch. 349)'),
    (v_topic_id, '18: "Libman-Sacks Endocarditis" in SLE is characterized by:', '["Large friable vegetations", "Small, sterile vegetations on both sides of the valves", "Infection by Staph aureus", "None"]', 1, 'Usually involves the mitral valve. (Step-Up)'),
    (v_topic_id, '19: The "Malar Rash" in SLE classically SPARES which area of the face?', '["Cheeks", "Bridge of the nose", "Nasolabial folds", "Forehead"]', 2, 'Helpful to distinguish from Rosacea or Seborrheic Dermatitis. (Pocket Medicine)'),
    (v_topic_id, '20: Which complement levels are typically DECREASED during an SLE flare?', '["C1 and C2", "C3 and C4", "C5 through C9", "None"]', 1, 'Consumption occurs due to immune complex formation. (Harrison''s Ch. 349)'),
    (v_topic_id, '21: "Lupus Nephritis" Class IV (Diffuse Proliferative) is treated aggressively with corticosteroids and:', '["Methotrexate", "Cyclophosphamide or Mycophenolate Mofetil", "Penicillin", "None"]', 1, 'Standard induction therapy for severe renal involvement. (Step-Up)'),
    (v_topic_id, '22: Which medication is used in ALL SLE patients (unless contraindicated) to reduce flares and improve survival?', '["Prednisone", "Hydroxychloroquine", "Methotrexate", "NSAIDs"]', 1, 'Reduces organ damage and thrombotic events. (Harrison''s Ch. 349)'),
    (v_topic_id, '23: "Antiphospholipid Syndrome" (APS) can occur in SLE and is characterized by arterial/venous thrombosis and:', '["Recurrent miscarriages", "Heavy menses", "Liver failure", "None"]', 0, 'High-yield association with Lupus. (Pocket Medicine)'),
    (v_topic_id, '24: A "false-positive RPR/VDRL" (syphilis test) in a Lupus patient is often due to:', '["Active syphilis", "Antiphospholipid antibodies (Lupus Anticoagulant)", "Low platelets", "None"]', 1, 'The test uses cardiolipin, which APS antibodies react with. (Step-Up)'),
    (v_topic_id, '25: "Jaccoud''s Arthropathy" in SLE mimics RA but differs because:', '["It is erosive", "The deformities are reducible", "It only affects the feet", "None"]', 1, 'Due to ligamentous laxity rather than joint destruction. (Harrison''s Ch. 349)'),
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: Which of the following is an "inflammatory" marker used to monitor disease activity in Rheumatology?', '["Creatinine", "ESR and CRP", "TSH", "Hemoglobin"]', 1, 'Erythrocyte Sedimentation Rate and C-Reactive Protein. (Harrison''s Ch. 351)'),
    (v_topic_id, '102: "Pannus" formation is a characteristic feature of:', '["Osteoarthritis", "Rheumatoid Arthritis", "Gout", "None"]', 1, 'Hypertrophied synovium invading cartilage and bone. (Step-Up)'),
    (v_topic_id, '103: RA patients with longstanding disease are at risk for subluxation of which joint during intubation?', '["Wrist", "Atlantoaxial (C1-C2) joint", "Hip", "Ankle"]', 1, 'Can lead to spinal cord compression; requires pre-op neck X-ray. (Pocket Medicine)'),
    (v_topic_id, '104: "Baker''s Cyst" (popliteal cyst) is a common complication of:', '["Shoulder injury", "Rheumatoid Arthritis or OA of the knee", "Ankle sprain", "None"]', 1, 'A bulge of synovial fluid behind the knee. (Harrison''s Ch. 351)'),
    (v_topic_id, '105: Which medication is a TNF-alpha RECEPTOR fusion protein (not a monoclonal antibody)?', '["Infliximab", "Adalimumab", "Etanercept", "Certolizumab"]', 2, '"Intercepts" TNF. (Step-Up)'),
    (v_topic_id, '106: "Anakinra" is a biologic agent that inhibits:', '["TNF-alpha", "IL-1", "IL-6", "B-cells"]', 1, 'An IL-1 receptor antagonist. (Pocket Medicine)'),
    (v_topic_id, '107: "Rituximab" targets which surface marker on B-cells?', '["CD4", "CD8", "CD20", "CD3"]', 2, 'Causes B-cell depletion. (Harrison''s Ch. 351)'),
    (v_topic_id, '108: "Tocilizumab" is a biologic agent that inhibits:', '["IL-1", "IL-6", "TNF", "JAK"]', 1, 'Used in RA and Giant Cell Arteritis. (Step-Up)'),
    (v_topic_id, '109: "Abatacept" works by:', '["Binding CD20", "Inhibiting T-cell costimulation (CTLA-4-Ig)", "Inhibiting JAK", "None"]', 1, 'Prevents T-cell activation. (Pocket Medicine)'),
    (v_topic_id, '110: "Tofacitinib" is a small molecule that inhibits:', '["TNF", "Janus Kinases (JAK)", "IL-17", "None"]', 1, 'An oral DMARD. (Harrison''s Ch. 351)'),
    (v_topic_id, '111: Which SLE manifestation is MOST LIKELY to be exacerbated by UV light exposure?', '["Arthritis", "Malar rash and photosensitivity", "Kidney disease", "None"]', 1, 'Patients must use high-SPF sunscreen. (Step-Up)'),
    (v_topic_id, '112: "Discoid Lupus" differs from SLE because it:', '["Is only internal", "Often limited to the skin with scarring lesions", "Is always fatal", "None"]', 1, 'Only 5-10% progress to systemic SLE. (Pocket Medicine)'),
    (v_topic_id, '113: "Lupus pernio" is actually a skin finding of ____, not SLE.', '["Sarcoidosis", "Gout", "RA", "None"]', 0, 'Purple/violaceous lesions on the nose/cheeks. (Harrison''s Ch. 360)'),
    (v_topic_id, '114: Which antibody is associated with a lower risk of renal disease in SLE?', '["Anti-dsDNA", "Anti-Ro/SSA", "Anti-centromere", "None"]', 1, 'Often seen in patients with primarily skin/joint disease. (Step-Up)'),
    (v_topic_id, '115: High-dose intravenous steroids used for Lupus flares are often colloquially called:', '["Pulse steroids", "Maintenance", "Bridge", "None"]', 0, 'Usually 1g of Methylprednisolone for 3 days. (Pocket Medicine)'),
    (v_topic_id, '116: "Belimumab" is a biologic approved for SLE that inhibits:', '["TNF", "B-lymphocyte stimulator (BLyS)", "IL-6", "None"]', 1, 'Reduces B-cell survival. (Harrison''s Ch. 349)'),
    (v_topic_id, '117: Which lab test is part of the diagnostic criteria for Antiphospholipid Syndrome?', '["ANA", "Lupus Anticoagulant", "RF", "Anti-CCP"]', 1, 'Also Anti-cardiolipin and Anti-beta2 glycoprotein I. (Step-Up)'),
    (v_topic_id, '118: A patient with APS and a history of thrombosis requires long-term anticoagulation with:', '["Aspirin only", "Warfarin (INR target 2-3)", "Clopidogrel", "None"]', 1, 'DOACs are generally avoided in high-risk triple-positive APS. (Pocket Medicine)'),
    (v_topic_id, '119: "Raynaud''s Phenomenon" consists of a sequence of color changes in the fingers: White, Blue, and:', '["Green", "Red", "Yellow", "Purple"]', 1, 'Ischemia, cyanosis, and reperfusion. (Harrison''s Ch. 353)'),
    (v_topic_id, '120: "Primary Raynaud''s" (Raynaud Disease) differs from Secondary Raynaud because it:', '["Has underlying tissue damage", "Lacks an underlying autoimmune disease", "Affects the heart", "None"]', 1, 'Usually benign and seen in young women. (Step-Up)'),
    (v_topic_id, '121: "Nailfold capillaroscopy" in Systemic Sclerosis reveals:', '["Normal loops", "Dilated/drop-out capillaries", "Excessive sweating", "None"]', 1, 'Useful tool to distinguish primary from secondary Raynaud. (Pocket Medicine)'),
    (v_topic_id, '122: "Watermelon Stomach" (GAVE) is a GI manifestation of:', '["SLE", "Systemic Sclerosis", "RA", "None"]', 1, 'Gastric Antral Vascular Ectasia. (Harrison''s Ch. 353)'),
    (v_topic_id, '123: Which medication is used for symptomatic dry mouth in Sjögren''s Syndrome?', '["Atropine", "Pilocarpine or Cevimeline", "Prednisone", "None"]', 1, 'Cholinergic agonists. (Step-Up)'),
    (v_topic_id, '124: "Primary Biliary Cholangitis" (PBC) is frequently associated with which rheumatologic condition?', '["Gout", "Sjögren''s Syndrome", "OA", "None"]', 1, 'Up to 30% overlap. (Pocket Medicine)'),
    (v_topic_id, '125: "Mechanic''s hands" in myositis are characterized by:', '["Soft palms", "Fissuring and hyperkeratosis of the finger pads", "Long nails", "None"]', 1, 'Associated with anti-synthetase syndrome. (Harrison''s Ch. 358)'),
    (v_topic_id, '126: Proximal muscle weakness in myositis typically makes it difficult to:', '["Write with a pen", "Comb hair or rise from a chair", "Button a shirt", "None"]', 1, 'Affects large muscle groups of the shoulders and hips. (Step-Up)'),
    (v_topic_id, '127: Muscle biopsy in "Polymyositis" shows:', '["Perifascicular atrophy", "Endomysial inflammation (CD8+ T-cells)", "Inclusion bodies", "None"]', 1, 'Inflammation is within the muscle fascicle. (Pocket Medicine)'),
    (v_topic_id, '128: Muscle biopsy in "Dermatomyositis" classically shows:', '["Endomysial inflammation", "Perifascicular atrophy and perivascular inflammation (CD4+)", "Normal tissue", "None"]', 1, 'Inflammation is around the fascicle. (Harrison''s Ch. 358)'),
    (v_topic_id, '129: "Shawl sign" in Dermatomyositis is a rash located on the:', '["Legs", "Upper back and shoulders", "Abdomen", "None"]', 1, 'V-sign is on the chest. (Step-Up)'),
    (v_topic_id, '130: Which medication class should be AVOIDED in patients with myositis and ILD?', '["Steroids", "Methotrexate (potentially pneumotoxic)", "Azathioprine", "None"]', 1, 'Must monitor lung function closely. (Pocket Medicine)'),
    (v_topic_id, '131: "Ankylosing Spondylitis" pain is unique because it:', '["Is worse in the evening", "Improves with exercise and is worse at rest", "Is only in the neck", "None"]', 1, 'Key feature of inflammatory back pain. (Harrison''s Ch. 355)'),
    (v_topic_id, '132: "Enthesitis" (inflammation where tendons attach to bone) is a hallmark of:', '["RA", "Spondyloarthropathies", "SLE", "None"]', 1, 'Common sites: Achilles tendon, plantar fascia. (Step-Up)'),
    (v_topic_id, '133: "Syndesmophytes" in Spondyloarthropathies are:', '["Horizontal bone spurs", "Vertical calcifications of the annulus fibrosus", "Fractures", "None"]', 1, 'Connect vertebral bodies. (Pocket Medicine)'),
    (v_topic_id, '134: In Ankylosing Spondylitis, "chest expansion" may be limited due to:', '["Pneumonia", "Costovertebral joint involvement", "Asthma", "None"]', 1, 'Can lead to restrictive lung disease. (Harrison''s Ch. 355)'),
    (v_topic_id, '135: What is the first-line pharmacotherapy for Ankylosing Spondylitis?', '["Methotrexate", "NSAIDs", "Steroids", "Hydroxychloroquine"]', 1, 'Methotrexate has little effect on axial (spinal) disease. (Step-Up)'),
    (v_topic_id, '136: Which biologic class is most effective for axial Ankylosing Spondylitis?', '["B-cell inhibitors", "TNF-alpha inhibitors or IL-17 inhibitors (e.g., Secukinumab)", "JAK inhibitors", "None"]', 1, 'Used when NSAIDs fail. (Pocket Medicine)'),
    (v_topic_id, '137: "Reactive Arthritis" typically occurs ____ weeks after the inciting infection.', '["1-4", "12-20", "52", "None"]', 0, 'Asymmetric oligoarthritis of the lower limbs. (Harrison''s Ch. 355)'),
    (v_topic_id, '138: "Circinate balanitis" is a painless penile rash seen in:', '["Syphilis", "Reactive Arthritis", "Lyme", "None"]', 1, 'High-yield board finding. (Step-Up)'),
    (v_topic_id, '139: "Nail pitting" and "onycholysis" (separation of nail from bed) are clues for:', '["RA", "Psoriatic Arthritis", "OA", "None"]', 1, 'Seen in 80% of those with psoriatic joint disease. (Pocket Medicine)'),
    (v_topic_id, '140: "Arthritis mutilans" is a severe, destructive form of:', '["OA", "Psoriatic Arthritis", "Gout", "None"]', 1, 'Causes "telescoping" of the digits. (Harrison''s Ch. 355)'),
    (v_topic_id, '141: "Jaw claudication" (pain with chewing) is a classic symptom of:', '["TMJ disorder", "Giant Cell Arteritis", "Stroke", "None"]', 1, 'High specificity for GCA. (Step-Up)'),
    (v_topic_id, '142: What is the definitive diagnostic test for Giant Cell Arteritis?', '["MRI Brain", "Temporal Artery Biopsy", "ESR", "None"]', 1, 'Requires a long segment (2-3 cm) due to skip lesions. (Pocket Medicine)'),
    (v_topic_id, '143: "Polymyalgia Rheumatica" (PMR) typically presents with an ESR of:', '["<10", ">40-50", "0", "None"]', 1, 'Usually dramatically high. (Harrison''s Ch. 356)'),
    (v_topic_id, '144: Treatment of PMR involves low-dose ____.', '["Methotrexate", "Prednisone (e.g., 10-20 mg/day)", "NSAIDs", "None"]', 1, 'Symptom relief is usually immediate. (Step-Up)'),
    (v_topic_id, '145: "Takayasu Arteritis" primarily affects the ____ and its main branches.', '["Capillaries", "Aorta", "Veins", "None"]', 1, 'Can cause limb claudication and bruits. (Pocket Medicine)'),
    (v_topic_id, '146: "Polyarteritis Nodosa" is a ____-vessel vasculitis.', '["Small", "Medium", "Large", "None"]', 1, 'Involves necrotizing inflammation of arteries. (Harrison''s Ch. 356)'),
    (v_topic_id, '147: Which medium-vessel vasculitis is the leading cause of acquired heart disease in children in developed countries?', '["PAN", "Kawasaki Disease", "GPA", "None"]', 1, '"Mucocutaneous lymph node syndrome." (Step-Up)'),
    (v_topic_id, '148: "Granulomatosis with Polyangiitis" (GPA) classically involves which triad?', '["Heart, Liver, Spleen", "Upper respiratory, Lungs, Kidneys", "Skin, Joints, Brain", "None"]', 1, 'Presents with sinusitis, nodules/cavities, and GN. (Pocket Medicine)'),
    (v_topic_id, '149: "Nasal bridge collapse" (Saddle nose deformity) can occur in:', '["RA", "GPA (Wegener''s) or Relapsing Polychondritis", "Lupus", "None"]', 1, 'Due to destruction of the nasal cartilage. (Harrison''s Ch. 356)'),
    (v_topic_id, '150: "Microscopic Polyangiitis" (MPA) differs from GPA by having NO:', '["Renal disease", "Granulomas on biopsy", "p-ANCA", "None"]', 1, 'Non-granulomatous vasculitis. (Step-Up)'),
    (v_topic_id, '151: "Churg-Strauss" (EGPA) patients almost always have a history of:', '["Smoking", "Asthma and Allergic Rhinitis", "Diabetes", "None"]', 1, 'Eosinophilia is a hallmark. (Pocket Medicine)'),
    (v_topic_id, '152: "Cryoglobulins" are proteins that precipitate at ____ temperatures.', '["Body", "Cold", "Hot", "None"]', 1, 'Associated with Hepatitis C. (Harrison''s Ch. 356)'),
    (v_topic_id, '153: "Behçet''s Disease" is most common in populations along the:', '["Equator", "Silk Road (Mediterranean to East Asia)", "Arctic Circle", "None"]', 1, 'Associated with HLA-B51. (Step-Up)'),
    (v_topic_id, '154: "Livedo reticularis" (lacy, reddish-blue skin pattern) can be a sign of:', '["Vasculitis or APS", "Normal aging", "Sunburn", "None"]', 0, 'Due to impaired blood flow in small vessels. (Pocket Medicine)'),
    (v_topic_id, '155: A "purpuric" rash that is palpable is a hallmark of:', '["Thrombocytopenia", "Small-vessel Vasculitis (Leukocytoclastic)", "Drug allergy", "None"]', 1, 'Non-blanching because blood has leaked out. (Harrison''s Ch. 356)'),
    (v_topic_id, '156: "Colchicine" works by inhibiting ____ polymerization.', '["DNA", "Microtubule", "Protein", "None"]', 1, 'Inhibits neutrophil chemotaxis. (Step-Up)'),
    (v_topic_id, '157: "Probenecid" is a uricosuric agent that works by:', '["Inhibiting production", "Increasing renal excretion of uric acid", "Breaking down crystals", "None"]', 1, 'Requires good renal function and no history of kidney stones. (Pocket Medicine)'),
    (v_topic_id, '158: What is the goal serum uric acid level for a patient with chronic tophaceous gout?', '["<10 mg/dL", "<6 mg/dL (or <5 for severe disease)", "0 mg/dL", "None"]', 1, '"Treat to target." (Harrison''s Ch. 362)'),
    (v_topic_id, '159: "Pegloticase" is used for refractory gout and works as a/an:', '["Uricase enzyme (converts urate to allantoin)", "Xanthine oxidase inhibitor", "NSAID", "None"]', 0, 'IV infusion for severe, erosive gout. (Step-Up)'),
    (v_topic_id, '160: "Hemochromatosis" is a classic metabolic cause of:', '["RA", "Pseudogout (CPPD)", "SLE", "None"]', 1, 'Look for "hook-like" osteophytes at the MCPs. (Pocket Medicine)'),
    (v_topic_id, '161: "Osteophytes" are colloquially known as:', '["Bone spurs", "Cysts", "Fractures", "None"]', 0, 'Common feature of OA. (Harrison''s Ch. 361)'),
    (v_topic_id, '162: Which OA site is MOST associated with obesity?', '["Hand", "Knee", "Shoulder", "Elbow"]', 1, 'Weight-bearing joints are heavily affected. (Step-Up)'),
    (v_topic_id, '163: "Erosive Osteoarthritis" typically involves the:', E'["Hip", "Hand (IP joints) and shows \\"gull-wing\\" appearance", "Spine", "None"]', 1, 'A more aggressive, inflammatory variant of OA. (Pocket Medicine)'),
    (v_topic_id, '164: "Spondylosis" is a general term for OA of the:', '["Shoulder", "Spine", "Hip", "None"]', 1, 'Involves disc degeneration and facet joint OA. (Harrison''s Ch. 361)'),
    (v_topic_id, '165: "Fibromyalgia" patients often report "Fibro-fog," which refers to:', '["Vision loss", "Cognitive dysfunction/memory issues", "Hearing loss", "None"]', 1, 'Part of the systemic nature of the syndrome. (Step-Up)'),
    (v_topic_id, '166: Which medication class is FDA-approved for Fibromyalgia?', '["Opioids", "SNRIs (e.g., Duloxetine) and Gabapentinoids (Pregabalin)", "Biologics", "None"]', 1, 'Tricyclic antidepressants (Amitriptyline) are also used. (Pocket Medicine)'),
    (v_topic_id, '167: "Septic Arthritis" in a prosthetic joint is most commonly caused by:', '["Coagulase-negative staphylococci (e.g., S. epidermidis)", "E. coli", "Virus", "None"]', 0, 'Biofilm formation makes treatment difficult. (Harrison''s Ch. 138)'),
    (v_topic_id, '168: "Lyme Arthritis" typically presents in the ____ stage of Lyme disease.', '["Early localized", "Late", "Early disseminated", "Chronic"]', 1, 'Presents as a large-joint monoarthritis (usually knee). (Step-Up)'),
    (v_topic_id, '169: "Whipple''s Disease" (Tropheryma whipplei) can cause a migratory large-joint arthritis and:', '["Cough", "Diarrhea, malabsorption, and CNS symptoms", "Rash", "None"]', 1, 'Diagnosed with PAS-positive macrophages on small bowel biopsy. (Pocket Medicine)'),
    (v_topic_id, '170: "Charcot Joint" (Neuropathic Arthropathy) is a destructive arthritis resulting from loss of sensation, common in:', '["RA", "Diabetes Mellitus and Syphilis (Tabes Dorsalis)", "Gout", "None"]', 1, 'Typically affects the foot and ankle. (Harrison''s Ch. 361)'),
    (v_topic_id, '171: "Relapsing Polychondritis" is characterized by inflammation of ____ (ear, nose, trachea).', '["Bone", "Cartilage", "Muscle", "None"]', 1, 'Ear lobe is typically SPARED (no cartilage). (Step-Up)'),
    (v_topic_id, '172: "Sarcoidosis" can present with an acute triad of hilar lymphadenopathy, erythema nodosum, and polyarthritis known as:', '["Felty Syndrome", "Löfgren Syndrome", "Caplan Syndrome", "None"]', 1, 'Has an excellent prognosis. (Pocket Medicine)'),
    (v_topic_id, '173: "Erythema Nodosum" presents as painful, red nodules on the shins and is a sign of:', '["Septic arthritis", "Systemic inflammation (Sarcoid, IBD, Strep, etc.)", "Gout", "None"]', 1, 'Panniculitis (inflammation of fat). (Harrison''s Ch. 360)'),
    (v_topic_id, '174: "Relapsing Polychondritis" can involve the upper airway, potentially causing:', '["Pneumonia", "Tracheal collapse", "Asthma", "None"]', 1, 'Requires aggressive monitoring of respiratory function. (Step-Up)'),
    (v_topic_id, '175: Which antibody is associated with an increased risk of Neonatal Lupus and Congenital Heart Block?', '["Anti-dsDNA", "Anti-Ro (SS-A)", "Anti-centromere", "None"]', 1, 'Ro and La cross the placenta. (Pocket Medicine)'),
    (v_topic_id, '176: "Adult-Onset Still''s Disease" (AOSD) presents with high spiking fevers, arthritis, and a/an:', '["Itchy hives", "Evanescent (salmon-colored) rash", "Black spots", "None"]', 1, 'Associated with very high Ferritin levels. (Harrison''s Ch. 351)'),
    (v_topic_id, '177: "Ferritin" levels in Adult-Onset Still''s Disease are often:', '["Low", "Normal", "Markedly elevated (>1000 ng/mL)", "None"]', 2, 'Diagnostic clue in a patient with FUO and rash. (Step-Up)'),
    (v_topic_id, '178: "Parvovirus B19" infection in adults can mimic which autoimmune disease?', '["SLE", "Rheumatoid Arthritis", "Gout", "None"]', 1, 'Causes an acute, symmetric small-joint polyarthritis. (Pocket Medicine)'),
    (v_topic_id, '179: "Chikungunya" virus is a mosquito-borne infection known for causing:', '["Blindness", "Severe, chronic polyarthritis", "Liver failure", "None"]', 1, 'Name means "that which bends up" in Makonde. (Harrison''s Ch. 200)'),
    (v_topic_id, '180: "Osteonecrosis" (Avascular Necrosis) of the femoral head is a major complication of chronic:', '["Methotrexate use", "Glucocorticoid (Steroid) use", "NSAIDs", "None"]', 1, 'Also linked to alcohol and trauma. (Step-Up)'),
    (v_topic_id, '181: "Paget''s Disease of Bone" is a disorder of bone remodeling that shows:', '["Low Alkaline Phosphatase", "Elevated Alkaline Phosphatase with normal Calcium/Phosphate", "High Calcium", "None"]', 1, 'Increases risk of osteosarcoma and high-output heart failure. (Pocket Medicine)'),
    (v_topic_id, '182: "Bisphosphonates" are used in Osteoporosis and Paget''s; they work by:', '["Inhibiting osteoblasts", "Inhibiting osteoclasts", "Increasing Vitamin D", "None"]', 1, 'Reduces bone resorption. (Harrison''s Ch. 363)'),
    (v_topic_id, '183: A rare but serious side effect of high-dose Bisphosphonate therapy is:', '["Liver failure", "Osteonecrosis of the Jaw (ONJ)", "Blindness", "None"]', 1, 'Also atypical femoral fractures. (Step-Up)'),
    (v_topic_id, '184: "Denosumab" is a biologic for osteoporosis that inhibits:', '["TNF", "RANK-Ligand", "IL-1", "None"]', 1, 'Prevents osteoclast maturation. (Pocket Medicine)'),
    (v_topic_id, '185: "Teriparatide" is a recombinant form of which hormone used to build bone?', '["Thyroxine", "Parathyroid Hormone (PTH)", "Insulin", "Glucagon"]', 1, 'Given intermittently to stimulate osteoblasts. (Harrison''s Ch. 363)'),
    (v_topic_id, '186: "Synovial fluid analysis" with WBC 2,000 - 50,000 is classified as:', '["Non-inflammatory", "Inflammatory", "Septic", "Hemorrhagic"]', 1, 'Seen in RA, Gout, and Spondyloarthropathies. (Step-Up)'),
    (v_topic_id, '187: "Synovial fluid" with WBC < 2,000 is classified as:', '["Inflammatory", "Non-inflammatory", "Septic", "None"]', 1, 'Typical of Osteoarthritis. (Pocket Medicine)'),
    (v_topic_id, '188: "Synovial fluid" that is bloody is often due to:', '["Gout", "Trauma, Hemophilia, or Pigmented Villonodular Synovitis (PVNS)", "RA", "None"]', 1, 'Requires investigation for coagulopathy. (Harrison''s Ch. 351)'),
    (v_topic_id, '189: "D-Penicillamine" is an old DMARD and chelating agent used for:', '["Lupus", "Wilson''s Disease and Cystinuria", "Gout", "None"]', 1, 'Rarely used for RA today. (Step-Up)'),
    (v_topic_id, '190: "Leflunomide" inhibits which pathway?', '["TNF", "Pyrimidine synthesis (DHODH inhibitor)", "Purine synthesis", "None"]', 1, 'An alternative to Methotrexate. (Pocket Medicine)'),
    (v_topic_id, '191: "Sulfasalazine" is a DMARD that is safe in:', '["Renal failure", "Pregnancy (if folic acid is given)", "Sulfa allergy", "None"]', 1, 'Commonly used in mild RA and IBD-arthritis. (Harrison''s Ch. 351)'),
    (v_topic_id, '192: "Azathioprine" is metabolized by which enzyme, requiring baseline screening?', '["ALT", "TPMT (Thiopurine Methyltransferase)", "G6PD", "None"]', 1, 'Deficiency leads to severe bone marrow toxicity. (Step-Up)'),
    (v_topic_id, '193: "Cyclophosphamide" carries a high risk of which specific toxicity?', '["Liver failure", "Hemorrhagic Cystitis and Bladder Cancer", "Blindness", "None"]', 1, 'Co-administered with Mesna and hydration. (Pocket Medicine)'),
    (v_topic_id, '194: "Mycophenolate Mofetil" (MMF) works by inhibiting:', '["TNF", "Inosine monophosphate dehydrogenase (Purine synthesis)", "JAK", "None"]', 1, 'First-line for Lupus Nephritis induction. (Harrison''s Ch. 349)'),
    (v_topic_id, '195: "Canakinumab" is a biologic agent that inhibits:', '["IL-6", "IL-1 beta", "TNF", "IL-17"]', 1, 'Used in periodic fever syndromes and refractory gout. (Step-Up)'),
    (v_topic_id, '196: "Ustekinumab" inhibits which interleukins?', '["IL-1", "IL-12 and IL-23", "IL-6", "None"]', 1, 'Used in Psoriasis and Psoriatic Arthritis. (Pocket Medicine)'),
    (v_topic_id, '197: "Secukinumab" is a biologic that inhibits:', '["TNF", "IL-17A", "IL-23", "None"]', 1, 'Effective for Ankylosing Spondylitis and Psoriatic Arthritis. (Harrison''s Ch. 355)'),
    (v_topic_id, '198: "Anklosing Spondylitis" patients have a high incidence of:', '["Lung cancer", "IgA Nephropathy", "Liver failure", "None"]', 1, 'Can present with hematuria. (Step-Up)'),
    (v_topic_id, '199: "Relapsing Polychondritis" patients can develop what cardiac issue?', '["MI", "Aortic Aneurysm and Regurgitation", "AV block", "None"]', 1, 'Due to inflammation of the aortic root. (Pocket Medicine)'),
    (v_topic_id, '200: "Amyloidosis" (AA type) is a late complication of chronic inflammation like RA, leading to:', '["Heart failure", "Nephrotic syndrome (Proteinuria)", "Liver failure", "None"]', 1, 'AA Amyloid is derived from Serum Amyloid A. (Harrison''s Ch. 104)');
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '201: A patient with sudden "curtain-like" vision loss and high ESR should be evaluated for:', '["Retinal detachment", "Giant Cell Arteritis", "Migraine", "Stroke"]', 1, 'Medical emergency; requires IV steroids. (Step-Up)'),
    (v_topic_id, '202: "Erythromelalgia" is a rare condition with red, burning hands/feet seen in:', '["Gout", "Myeloproliferative disorders or Polycythemia Vera", "RA", "None"]', 1, 'Can be treated with Aspirin. (Pocket Medicine)'),
    (v_topic_id, '203: "Raynaud''s" that is asymmetric or causes digital ulcers is more likely to be:', '["Primary", "Secondary (associated with Systemic Sclerosis/Lupus)", "Normal", "None"]', 1, 'Requires comprehensive workup. (Harrison''s Ch. 353)'),
    (v_topic_id, '204: "Subchondral cysts" on X-ray are a feature of:', '["RA", "Osteoarthritis", "Septic arthritis", "None"]', 1, 'Occurs when synovial fluid is forced into the bone. (Step-Up)'),
    (v_topic_id, '205: "Enthesophyte" at the calcaneus is colloquially called a:', '["Heel spur", "Bunion", "Tophi", "None"]', 0, 'Seen in Spondyloarthropathies. (Pocket Medicine)'),
    (v_topic_id, '206: "Lupus Anticoagulant" ironically causes:', '["Bleeding", "Thrombosis (Clotting)", "Anemia", "None"]', 1, 'Prolongs the aPTT in vitro but causes clotting in vivo. (Harrison''s Ch. 349)'),
    (v_topic_id, '207: "Anti-Scl-70" is directed against which enzyme?', '["RNA Polymerase", "DNA Topoisomerase I", "Synthetase", "None"]', 1, 'Marker for Diffuse Systemic Sclerosis. (Step-Up)'),
    (v_topic_id, '208: "Sclerodactyly" refers to:', '["Extra fingers", "Thickened, tight skin of the fingers", "Joint fusion", "None"]', 1, '"Claw-hand" appearance in scleroderma. (Pocket Medicine)'),
    (v_topic_id, '209: "Pathergy test" (positive if a papule forms at a needle prick site) is for:', '["Lupus", "Behçet''s Disease", "GPA", "None"]', 1, 'Indicates skin hyper-reactivity. (Harrison''s Ch. 356)'),
    (v_topic_id, '210: "Homan''s sign" is not reliable for DVT, but "Moses'' sign" (pain on calf squeeze) can be seen in:', '["Gout", "DVT or Ruptured Baker''s Cyst", "RA", "None"]', 1, 'Ruptured Baker''s cyst mimics DVT ("Pseudo-DVT"). (Step-Up)'),
    (v_topic_id, '211: "Anti-mitochondrial antibody" (AMA) is the hallmark of:', '["PSC", "Primary Biliary Cholangitis (PBC)", "Sjögren''s", "None"]', 1, 'Associated with dry eyes/mouth in overlap. (Pocket Medicine)'),
    (v_topic_id, '212: "IgG4-Related Disease" can cause pancreatitis, parotitis, and:', '["Joint erosions", "Retroperitoneal fibrosis", "Skin ulcers", "None"]', 1, 'A fibro-inflammatory condition. (Harrison''s Ch. 359)'),
    (v_topic_id, '213: "Saddle nose" + "Hearing loss" + "Hematuria" = ?', '["GPA (Wegener''s)", "Microscopic polyangiitis", "PAN", "None"]', 0, 'PR3-ANCA positive vasculitis. (Step-Up)'),
    (v_topic_id, '214: "Asthma" + "Eosinophilia" + "Neuropathy" = ?', '["GPA", "EGPA (Churg-Strauss)", "Lyme", "None"]', 1, 'MPO-ANCA positive vasculitis. (Pocket Medicine)'),
    (v_topic_id, '215: "Hepatitis B" + "Abdominal pain" + "Renal microaneurysms" = ?', '["GPA", "Polyarteritis Nodosa (PAN)", "MPA", "None"]', 1, 'Classic board association. (Harrison''s Ch. 356)'),
    (v_topic_id, '216: "Young Asian female" + "Weak pulses" + "Bruits" = ?', '["Takayasu Arteritis", "GCA", "PAN", "None"]', 0, '"Pulseless disease." (Step-Up)'),
    (v_topic_id, '217: "Elderly female" + "Scalp tenderness" + "Jaw pain" = ?', '["Stroke", "Giant Cell Arteritis", "TMJ", "None"]', 1, 'Monitor for vision loss. (Pocket Medicine)'),
    (v_topic_id, '218: "Child" + "Strawberry tongue" + "Desquamation" = ?', '["GPA", "Kawasaki Disease", "Measles", "None"]', 1, 'Requires Aspirin and IVIG. (Harrison''s Ch. 356)'),
    (v_topic_id, '219: "Child" + "Palpable purpura" + "Abdominal pain" + "Arthritis" = ?', '["ITP", "Henoch-Schönlein Purpura (IgA Vasculitis)", "TTP", "None"]', 1, 'Can have renal involvement (IgA nephropathy). (Step-Up)'),
    (v_topic_id, '220: "Anti-U1 RNP" antibody is the marker for:', '["SLE", "Mixed Connective Tissue Disease (MCTD)", "Sjögren''s", "None"]', 1, 'Overlaps SLE, Scleroderma, and Myositis. (Pocket Medicine)'),
    (v_topic_id, '221: "Anti-Jo-1" is specifically an anti-____ antibody.', '["DNA", "Histidyl-tRNA synthetase", "Topoisomerase", "None"]', 1, 'Most common antisynthetase antibody. (Harrison''s Ch. 358)'),
    (v_topic_id, '222: "Gottron''s sign" is different from "Gottron''s papules" because it is:', '["Itchy", "Macular erythema (redness) over the knuckles", "Ulcerated", "None"]', 1, 'Both are pathognomonic for dermatomyositis. (Step-Up)'),
    (v_topic_id, '223: "Holster sign" in Dermatomyositis is a rash on the:', '["Chest", "Lateral thighs", "Forearms", "None"]', 1, 'Symmetrical violaceous rash. (Pocket Medicine)'),
    (v_topic_id, '224: "V-sign" in Dermatomyositis is a rash on the:', '["Upper chest/neck", "Back", "Ears", "None"]', 0, 'Photodistributed erythema. (Harrison''s Ch. 358)'),
    (v_topic_id, '225: "Mechanic''s hands" can also be seen in people who:', '["Play piano", "Do heavy manual labor (mimics the disease)", "Swim", "None"]', 1, 'Must distinguish true dermatomyositis from occupational exposure. (Step-Up)'),
    (v_topic_id, '226: "Juvenile Idiopathic Arthritis" (JIA) previously known as JRA requires symptoms for at least:', '["2 weeks", "6 weeks", "6 months", "1 year"]', 1, 'In a patient <16 years old. (Pocket Medicine)'),
    (v_topic_id, '227: "Systemic JIA" (Still''s disease) is characterized by fever, rash, and:', '["Splenomegaly and Serositis", "Hearing loss", "Blindness", "None"]', 0, 'Can lead to Macrophage Activation Syndrome (MAS). (Harrison''s Ch. 351)'),
    (v_topic_id, '228: "Macrophage Activation Syndrome" (MAS) is a life-threatening form of ____ seen in systemic JIA.', '["Sepsis", "Hemophagocytic Lymphohistiocytosis (HLH)", "Anaphylaxis", "None"]', 1, 'Presents with falling cell counts and very high ferritin. (Step-Up)'),
    (v_topic_id, '229: "Oligoarthritis JIA" (the most common type) has a high risk of:', '["Heart failure", "Asymptomatic Anterior Uveitis", "Renal failure", "None"]', 1, 'Requires regular slit-lamp exams. (Pocket Medicine)'),
    (v_topic_id, '230: "Uveitis" in JIA is often associated with which antibody?', '["RF", "ANA", "Anti-dsDNA", "None"]', 1, 'ANA-positive girls are at highest risk. (Harrison''s Ch. 351)'),
    (v_topic_id, '231: "Sarcoidosis" in the eye most commonly presents as:', '["Cataract", "Granulomatous Uveitis", "Glaucoma", "None"]', 1, 'Can also cause lacrimal gland enlargement. (Step-Up)'),
    (v_topic_id, '232: "Heerfordt Syndrome" in Sarcoidosis consists of Uveitis, Parotid enlargement, and:', '["Facial nerve palsy", "Hearing loss", "Rash", "None"]', 0, 'Also known as uveoparotid fever. (Pocket Medicine)'),
    (v_topic_id, '233: "Hypercalcemia" in Sarcoidosis is due to:', '["Bone destruction", "Increased 1-alpha-hydroxylase in granulomas (Vitamin D activation)", "Cancer", "None"]', 1, 'Leads to increased calcium absorption. (Harrison''s Ch. 360)'),
    (v_topic_id, '234: "ACE" (Angiotensin-Converting Enzyme) levels in Sarcoidosis are:', '["Always normal", "Often elevated but non-specific", "Always low", "None"]', 1, 'Used to monitor disease but not for diagnosis. (Step-Up)'),
    (v_topic_id, '235: "Erythema Nodosum" + "Hilar Lymphadenopathy" + "Arthritis" = ?', '["Löfgren Syndrome", "Behçet''s", "Lupus", "None"]', 0, 'Acute, self-limiting sarcoidosis. (Pocket Medicine)'),
    (v_topic_id, '236: "Osteoarthritis" of the spine can cause "Spinal Stenosis," resulting in:', '["Acute back pain", "Neurogenic claudication (leg pain relieved by leaning forward)", "Arm pain", "None"]', 1, '"Shopping cart sign." (Harrison''s Ch. 361)'),
    (v_topic_id, '237: "Neurogenic claudication" (OA) differs from "Vascular claudication" (PAD) because it is:', '["Relieved by standing", "Relieved by sitting or bending forward (flexion)", "Worsened by rest", "None"]', 1, 'Flexion opens the spinal canal. (Step-Up)'),
    (v_topic_id, '238: "Diffuse Idiopathic Skeletal Hyperostosis" (DISH) is characterized by:', '["Joint erosions", "Flowing calcifications along the anterior longitudinal ligament of the spine", "Spinal fusion", "None"]', 1, '"Dripping candle wax" appearance. (Pocket Medicine)'),
    (v_topic_id, '239: "DISH" classically SPARES the:', '["Thoracic spine", "Sacroiliac (SI) joints and disc spaces", "Neck", "None"]', 1, 'Helps distinguish it from Ankylosing Spondylitis. (Harrison''s Ch. 361)'),
    (v_topic_id, '240: "Gout" is more common in men until age ____, when it equalizes with women.', '["30", "50 (Post-menopause)", "70", "None"]', 1, 'Estrogen has uricosuric effects. (Step-Up)'),
    (v_topic_id, '241: "Tumor Lysis Syndrome" can cause extreme hyperuricemia and:', '["Liver failure", "Acute Urate Nephropathy (Renal failure)", "Bone marrow failure", "None"]', 1, 'Due to crystal deposition in renal tubules. (Pocket Medicine)'),
    (v_topic_id, '242: "Rasburicase" is used in Tumor Lysis Syndrome and works as a:', '["Xanthine oxidase inhibitor", "Recombinant Urate Oxidase (enzyme)", "Steroid", "None"]', 1, 'Quickly lowers uric acid levels. (Harrison''s Ch. 362)'),
    (v_topic_id, '243: "Lead poisoning" is a known risk factor for:', '["RA", "Saturnine Gout", "Lupus", "None"]', 1, 'Due to lead-induced renal tubular damage. (Step-Up)'),
    (v_topic_id, '244: "Milton''s line" or "Martel''s sign" (punched-out erosions with overhanging edges) is seen in:', '["RA", "Chronic Gout", "OA", "None"]', 1, 'Characteristic radiographic feature. (Pocket Medicine)'),
    (v_topic_id, '245: "Hydroxyapatite" crystal deposition disease primarily affects the:', '["Knee", "Shoulder (Calcific tendonitis)", "Small joints", "None"]', 1, 'Causes "Milwaukee Shoulder." (Harrison''s Ch. 362)'),
    (v_topic_id, '246: "Ehler-Danlos Syndrome" is a disorder of ____ synthesis.', '["Bone", "Collagen", "Elastin", "None"]', 1, 'Presents with joint hypermobility and skin hyperextensibility. (Step-Up)'),
    (v_topic_id, '247: "Marfan Syndrome" is a defect in the ____ gene.', '["Collagen", "Fibrillin-1", "Dystrophin", "None"]', 1, 'Presents with tall stature, arachnodactyly, and aortic root dilation. (Pocket Medicine)'),
    (v_topic_id, '248: "Arachnodactyly" refers to:', '["Extra fingers", "Long, thin fingers", "Short fingers", "None"]', 1, 'Seen in Marfan and EDS. (Harrison''s Ch. 363)'),
    (v_topic_id, '249: "Ectopia lentis" (dislocated lens) in Marfan Syndrome is typically ____.', '["Downward", "Upward and outward", "Inward", "None"]', 1, 'Distinguishes it from Homocystinuria (downward). (Step-Up)'),
    (v_topic_id, '250: "Pseudoxanthoma elasticum" is characterized by "plucked chicken" skin and:', '["Blindness", "Angioid streaks in the retina", "Heart failure", "None"]', 1, 'A disorder of elastic fibers. (Pocket Medicine)'),
    (v_topic_id, '251: "Takayasu Arteritis" Stage 1 is often:', '["Asymptomatic", "Non-specific (fever, weight loss, night sweats)", "Stroke", "None"]', 1, '"Pre-pulseless" stage. (Harrison''s Ch. 356)'),
    (v_topic_id, '252: "Giant Cell Arteritis" can cause large vessel involvement like:', '["Aortic Aneurysm", "Renal failure", "Skin ulcers", "None"]', 0, 'Requires long-term monitoring with imaging. (Step-Up)'),
    (v_topic_id, '253: "Buerger''s Disease" (Thromboangiitis Obliterans) on angiography shows:', '["String of beads", "Corkscrew collaterals", "Large aneurysms", "None"]', 1, 'Due to distal vessel occlusion. (Pocket Medicine)'),
    (v_topic_id, '254: "Cogan Syndrome" consists of interstitial keratitis and:', '["Fever", "Vestibulo-auditory symptoms (hearing loss, vertigo)", "Joint pain", "None"]', 1, 'A rare vasculitis syndrome. (Harrison''s Ch. 356)'),
    (v_topic_id, '255: "Relapsing Polychondritis" can be associated with which hematologic condition?', '["Anemia", "Myelodysplastic Syndrome (MDS)", "Leukemia", "None"]', 1, 'High-yield clinical association. (Step-Up)'),
    (v_topic_id, '256: "Hypocomplementemic Urticarial Vasculitis" (HUVS) is associated with which antibody?', '["Anti-dsDNA", "Anti-C1q antibodies", "ANA", "None"]', 1, 'Presents with chronic hives and systemic disease. (Pocket Medicine)'),
    (v_topic_id, '257: "Livedo racemosa" differs from livedo reticularis because it is:', '["Lighter", "Broken/irregular and indicates pathological vessel occlusion", "Transient", "None"]', 1, 'Seen in Sneddon Syndrome. (Harrison''s Ch. 356)'),
    (v_topic_id, '258: "Sneddon Syndrome" is the association of livedo racemosa and:', '["Kidney failure", "Recurrent ischemic strokes", "Arthritis", "None"]', 1, 'Often linked to Antiphospholipid Syndrome. (Step-Up)'),
    (v_topic_id, '259: "Palpable purpura" + "Low C4" + "Hepatitis C" = ?', '["GPA", "Cryoglobulinemic Vasculitis", "PAN", "None"]', 1, 'Type II or III cryoglobulinemia. (Pocket Medicine)'),
    (v_topic_id, '260: "Type I Cryoglobulinemia" is usually associated with:', '["Hepatitis C", "Multiple Myeloma or Waldenström macroglobulinemia", "Lupus", "None"]', 1, 'Monoclonal proteins. (Harrison''s Ch. 356)'),
    (v_topic_id, '261: "Cyclophosphamide" should be avoided in patients who want to:', '["Exercise", "Maintain fertility (causes gonadotoxicity)", "Eat sugar", "None"]', 1, 'Sperm/oocyte banking should be discussed. (Step-Up)'),
    (v_topic_id, '262: "Oprelvekin" is not a rheum drug, but "Abatacept" is unique because it is a/an:', '["Antibody", "Fusion protein (CTLA-4 fused to IgG1 Fc)", "Small molecule", "None"]', 1, 'Inhibits T-cell costimulation. (Pocket Medicine)'),
    (v_topic_id, '263: "Denosumab" discontinuation can lead to:', '["Liver failure", "Rapid rebound bone loss and vertebral fractures", "High fever", "None"]', 1, 'Must be followed by a bisphosphonate. (Harrison''s Ch. 363)'),
    (v_topic_id, '264: "Osteoarthritis" does NOT affect the:', '["Spine", "Shoulder (except after trauma)", "Hip", "Knee"]', 1, 'Shoulder OA is less common than in weight-bearing joints. (Step-Up)'),
    (v_topic_id, '265: "Septic arthritis" with "Gram-negative diplococci" is:', '["Staph", "Neisseria (Gonococcus or Meningococcus)", "E. coli", "None"]', 1, 'High-yield Gram stain finding. (Pocket Medicine)'),
    (v_topic_id, '266: "Relapsing Polychondritis" can cause a "Saddle Nose" deformity similar to:', '["Lupus", "GPA (Wegener''s)", "Gout", "None"]', 1, 'Due to cartilage destruction. (Harrison''s Ch. 356)'),
    (v_topic_id, '267: "Lupus" patients with "Anti-phospholipid antibodies" should AVOID which medication?', '["Methotrexate", "Estrogen-containing contraceptives", "Aspirin", "None"]', 1, 'Increases the risk of thromboembolic events. (Step-Up)'),
    (v_topic_id, '268: "Leflunomide" has a very long half-life; to remove it quickly, use:', '["Hemodialysis", "Cholestyramine washout", "Diuretics", "None"]', 1, 'Crucial in cases of toxicity or unplanned pregnancy. (Pocket Medicine)'),
    (v_topic_id, '269: "Hydroxychloroquine" is safe during ____.', '["Only sleep", "Pregnancy", "Nothing", "None"]', 1, 'Often continued in SLE patients who are pregnant. (Harrison''s Ch. 349)'),
    (v_topic_id, '270: "Methotrexate" is absolutely contraindicated in ____.', '["Men", "Pregnancy (Teratogenic)", "Elderly", "None"]', 1, 'Requires strict contraception. (Step-Up)'),
    (v_topic_id, '271: "Gout" patients should limit intake of:', '["Fiber", "Purine-rich foods (red meat, seafood) and high-fructose corn syrup", "Vitamin C", "None"]', 1, 'Also alcohol, especially beer. (Pocket Medicine)'),
    (v_topic_id, '272: "Vitamin C" and "Coffee" may actually ____ uric acid levels.', '["Raise", "Lower", "Not affect", "None"]', 1, 'Associated with lower gout risk. (Harrison''s Ch. 362)'),
    (v_topic_id, '273: "Acute Calcium Pyrophosphate Crystal Arthritis" is the official name for:', '["Gout", "Pseudogout", "RA", "None"]', 1, 'Clinically mimics gout. (Step-Up)'),
    (v_topic_id, '274: "Calcium hydroxyapatite" crystals are too small to be seen with light microscopy and require:', '["X-ray", "Alizarin Red stain", "Gram stain", "None"]', 1, 'Appear as "clumps" or "shiny coins." (Pocket Medicine)'),
    (v_topic_id, '275: "Milwaukee Shoulder" is a destructive arthropathy associated with:', '["Urate", "Calcium hydroxyapatite", "CPPD", "None"]', 1, 'Often seen in elderly women. (Harrison''s Ch. 362)'),
    (v_topic_id, '276: "Fibromyalgia" tender point count is now less used than the:', '["Widespread Pain Index (WPI) and Symptom Severity (SS) scale", "X-ray", "Blood test", "None"]', 0, 'Updated diagnostic criteria. (Step-Up)'),
    (v_topic_id, '277: "Polymyalgia Rheumatica" (PMR) is a disease of the ____ age group.', '["Pediatric", "Elderly (>50 years)", "Young adult", "None"]', 1, 'Almost never seen in patients under 50. (Pocket Medicine)'),
    (v_topic_id, '278: "Giant Cell Arteritis" can cause a/an ____ bruit.', '["Abdominal", "Carotid or Axillary", "Heart", "None"]', 1, 'Sign of large vessel involvement. (Harrison''s Ch. 356)'),
    (v_topic_id, '279: "Takayasu Arteritis" can cause "Reversed Coarctation," where BP is:', '["Higher in arms than legs", "Lower in arms than legs", "Normal", "None"]', 1, 'Due to stenosis of the subclavian arteries. (Step-Up)'),
    (v_topic_id, '280: "Kawasaki Disease" mnemonic: "CRASH and Burn." The "Burn" stands for:', '["Skin burn", "5 days of high Fever", "Reflux", "None"]', 1, 'C=Conjunctivitis, R=Rash, A=Adenopathy, S=Strawberry tongue, H=Hands/feet. (Pocket Medicine)'),
    (v_topic_id, '281: "Behçet''s" ocular disease can cause "hypopyon," which is:', '["A hole in the iris", "Pus in the anterior chamber", "Vision loss", "None"]', 1, 'A dramatic sign of severe inflammation. (Harrison''s Ch. 356)'),
    (v_topic_id, '282: "Anti-synthetase syndrome" includes Myositis, ILD, Raynaud, and:', '["Fever and Mechanic''s hands", "Blindness", "Diarrhea", "None"]', 0, 'High-yield for advanced exams. (Step-Up)'),
    (v_topic_id, '283: "Scleroderma" GI involvement can cause "Pseudo-obstruction" due to:', '["Cancer", "Atrophy of smooth muscle and fibrosis", "Infection", "None"]', 1, 'Leads to severe dysmotility. (Pocket Medicine)'),
    (v_topic_id, '284: "Lupus Nephritis" diagnosis requires:', '["Blood test", "Renal biopsy", "Ultrasound", "None"]', 1, 'To determine the class (I-VI) and guide treatment. (Harrison''s Ch. 349)'),
    (v_topic_id, '285: "Anti-La" is almost always found in the presence of ____.', '["Anti-Ro", "RF", "Anti-dsDNA", "None"]', 0, 'Rarely found in isolation. (Step-Up)'),
    (v_topic_id, '286: "Paraneoplastic" myositis is most associated with which type of cancer in men?', '["Breast", "Lung or Prostate", "Skin", "None"]', 1, 'In women, ovarian cancer is high risk. (Pocket Medicine)'),
    (v_topic_id, '287: "Inclusion Body Myositis" (IBM) is more common in:', '["Young women", "Men > 50 years old", "Children", "None"]', 1, 'Most common inflammatory myopathy in the elderly. (Harrison''s Ch. 358)'),
    (v_topic_id, '288: "Sacroiliitis" on MRI is the earliest sign of:', '["RA", "Ankylosing Spondylitis", "OA", "None"]', 1, 'Involves bone marrow edema. (Step-Up)'),
    (v_topic_id, '289: "Aortic root dilation" in AS can lead to:', '["Mitral stenosis", "Aortic Regurgitation", "Stroke", "None"]', 1, 'Classic board association. (Pocket Medicine)'),
    (v_topic_id, '290: "Dermatomyositis" can cause "Calcinosis," especially in:', '["Elderly", "Children (Juvenile Dermatomyositis)", "Men", "None"]', 1, 'Can be extensive and debilitating. (Harrison''s Ch. 358)'),
    (v_topic_id, '291: "Anti-CCP" antibodies are more specific for RA because they:', '["Bind to collagen", "Recognize citrullinated proteins (post-translational modification)", "Are only in the joints", "None"]', 1, 'Citrullination is increased in the RA synovium. (Step-Up)'),
    (v_topic_id, '292: "RF" (Rheumatoid Factor) is an antibody (usually IgM) against the ____ portion of IgG.', '["Fab", "Fc", "Variable", "None"]', 1, 'Forms immune complexes. (Pocket Medicine)'),
    (v_topic_id, '293: "Felty Syndrome" patients have an increased risk of which malignancy?', '["Lung", "Non-Hodgkin Lymphoma", "Skin", "None"]', 1, 'Due to chronic immune stimulation. (Harrison''s Ch. 351)'),
    (v_topic_id, '294: "Methotrexate" toxicity can cause "leucopenia"; the "antidote" is:', '["Vitamin C", "Leucovorin (Folinic Acid)", "Iron", "None"]', 1, 'Bypasses the inhibited DHFR enzyme. (Step-Up)'),
    (v_topic_id, '295: "Hydroxychloroquine" does NOT cause:', '["Bone marrow suppression", "Retinal toxicity", "Rash", "None"]', 0, 'Relatively safe regarding the bone marrow. (Pocket Medicine)'),
    (v_topic_id, '296: "Gout" in a pre-menopausal woman should prompt investigation for:', '["Pregnancy", "Renal disease or Genetic disorders (e.g., Lesch-Nyhan)", "Stress", "None"]', 1, 'Unusual due to estrogen protection. (Harrison''s Ch. 362)'),
    (v_topic_id, '297: "Lesch-Nyhan Syndrome" is an X-linked deficiency of HGPRT, presenting with gout, intellectual disability, and:', '["Blindness", "Self-mutilation (biting lips/fingers)", "Liver failure", "None"]', 1, 'High-yield pediatric association. (Step-Up)'),
    (v_topic_id, '298: "Allopurinol" can cause a severe hypersensitivity syndrome (DRESS), especially in patients with the ____ allele.', '["HLA-B*2705", "HLA-B*5801 (especially Han Chinese/Thai/Korean)", "HLA-DR4", "None"]', 1, 'Requires screening in high-risk populations. (Pocket Medicine)'),
    (v_topic_id, '299: "Febuxostat" is a non-purine xanthine oxidase inhibitor used when:', '["Gout is mild", "Patient is intolerant to Allopurinol", "Patient has no joints", "None"]', 1, 'Carries a black box warning for cardiovascular death in some studies. (Harrison''s Ch. 362)'),
    (v_topic_id, '300: Final Pearl: Rheumatology is often the "Sherlock Holmes" of medicine because it requires:', '["Only blood tests", "Pattern recognition across multiple organ systems", "Surgery", "None"]', 1, 'Requires careful history and physical exam. (MediHelp Mastery)');
